package org.jfree.chart.plot;

import java.awt.Color;
import java.awt.Paint;
import java.awt.Stroke;
import java.io.*;
import java.math.*;
import java.util.*;
import org.jfree.chart.Stroke;
import org.jfree.chart.event.MarkerChangeEvent;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

public class ValueMarker_ValueMarker_TriageGen1Test {

    @Test
    public void testConstructorWithSingleValue() {
        double value = 10.5;
        ValueMarker marker = new ValueMarker(value);
        assertEquals(value, marker.getValue(), 1.0e-10);
    }

    @Test
    public void testConstructorWithPaintAndStroke() {
        double value = 20.0;
        Paint paint = Color.RED;
        Stroke stroke = new Stroke(1.0, BasicStrokeStyle.SOLID);
        ValueMarker marker = new ValueMarker(value, paint, stroke);

        assertEquals(value, marker.getValue(), 1.0e-10);
        // Note: Since super calls are internal, we verify via the value property 
        // and the fact that it doesn't throw exceptions.
    }

    @Test
    public void testConstructorFullArguments() {
        double value = 30.5;
        Paint paint = Color.BLUE;
        Stroke stroke = new Stroke(2.0, BasicStrokeStyle.SOLID);
        Paint outlinePaint = Color.BLACK;
        Stroke outlineStroke = new Stroke(1.0, BasicStrokeStyle.DASHED);
        float alpha = 0.5f;

        ValueMarker marker = new ValueMarker(value, paint, stroke, outlinePaint, outlineStroke, alpha);

        assertEquals(value, marker.getValue(), 1.0e-10);
    }

    @Test
    public void testSetValue() {
        ValueMarker marker = new ValueMarker(10.0);
        marker.setValue(50.5);
        assertEquals(50.5, marker.getValue(), 1.0e-10);
    }

    @Test
    public void testEquals() {
        ValueMarker marker1 = new ValueMarker(10.0);
        ValueMarker marker2 = new ValueMarker(10.0);
        ValueMarker marker3 = new ValueMarker(20.0);
        ValueMarker marker4 = new ValueMarker(10.0, Color.RED, new Stroke(1.0, BasicStrokeStyle.SOLID));

        // Test equality based on value (assuming equals is implemented as per standard JFreeChart patterns)
        assertEquals(marker1, marker2);
        assertNotEquals(marker1, marker3);
        assertNotEquals(marker1, null);
        assertNotEquals(marker1, "not a marker");

        // If equals implementation depends on more than just value, adjust accordingly.
        // Given the provided signature, we test the basic object equality logic.
        marker1.setValue(10.0);
        marker2.setValue(10.0);
        assertEquals(marker1, marker2);
    }

    // Helper class to mock Stroke if necessary, though JFreeChart usually provides one.
    // Since I cannot import external dependencies not provided, I assume Stroke is available.
    private static class BasicStrokeStyle {
        static final int SOLID = 1;
        static final int DASHED = 2;
    }
}
